package com.tpverp.backend.pdawork;
import static org.assertj.core.api.Assertions.*;import java.lang.reflect.Method;import java.util.Arrays;import org.junit.jupiter.api.Test;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
class PdaInventoryTraceControllerContractTest{@Test void exposesProtectedLocationsAndFefoLotContracts(){assertThat(PdaInventoryTraceController.class.getAnnotation(RequestMapping.class).value()).containsExactly("/api/v1/pda-inventory");assertThat(PdaInventoryTraceController.class.getAnnotation(PreAuthorize.class).value()).contains("GESTION_ALMACEN","STOCK_ADJUST","STOCK_TRANSFER");var gets=Arrays.stream(PdaInventoryTraceController.class.getDeclaredMethods()).filter(v->v.isAnnotationPresent(GetMapping.class)).map(Method::getName).toList();var posts=Arrays.stream(PdaInventoryTraceController.class.getDeclaredMethods()).filter(v->v.isAnnotationPresent(PostMapping.class)).map(Method::getName).toList();assertThat(gets).contains("locations","lots","fefo");assertThat(posts).contains("location","deactivate","receive","consume");}}